Method.Implementation:
q:idx="" ""
if ($g(handle)'=$$$MarcHANDLEXMAGIC) || '$d(handle("modified")) { 
  q ""
}

; kontrola prav na zdroj pro permalink
; TODO v pripade logicke databaze zkontrolovat, zda v ni zaznam skutecne je
s src=$p(idx,"*",1)
if '##class(i2.access).isSourceAccessible(src) {
  q ..tx("NORIGHTS")  ;"nejsou prava na zdroj"
}

s line=##class(User.MARC).getTagX(.handle,"969")_$c(31)
; 19.04.16 tt; nastaveni desiderat na 969f = N nebo D
; desidereata
if ($f(line,$c(31)_"fD"_$c(31)) || $f(line,$c(31)_"fN"_$c(31))) {
  q ..tx("NOREC") 
}

q ""

s iset=data("ISET") ; TODO ? $$$GETREQVAR("bpg")
if iset="basket" {
  s currZF=##class(i2.basket).zfDetailGet($p(data("IDX"),"*",1))
}
elseif iset'="" {  
  s isetInfo=##class(i2.dblink).getISetInfo(iset)
  s currZF=$p(isetInfo,$c(10),$$$cISetZF2)
} else {
  ;s currZF=##class(i2.config).getSourceDetailZF(##class(i2.common).currSourcesGetFirstZF(),$p(data("IDX"),"*",1))
  ; 17.09.25 ln; handlenet permalink vede na prvni zobrazovak
  s currZF=##class(i2.common).currSourcesGetFirstZF()
}

s zf=$$$GETREQVAR("zf")
if (zf'="") && (currZF'=zf) { 
  s currZF=zf
  if iset="basket" {
    d ##class(i2.basket).zfDetailSet(currZF)
  }
  elseif iset'="" {
    s $p(isetInfo,$c(10),$$$cISetZF2)=zf 
    d ##class(i2.dblink).setISetInfo(iset,isetInfo)
  }
}
s:currZF="" currZF="SHORT"  
s data("ZF_SEL")=currZF

s line=##class(User.MARC).getTagX(.handle,"969")_$c(31)
if $f(line,$c(31)_"fERASE"_$c(31)) {
  ; 17.09.25 ln; podpora tombstone page
  s data("ERASED")=1
  s data("TBC")=$$$getTagX(.handle,"Tbca")
  s data("DOI")="https://doi.org/"_##class(User.MARC).getTagX(.handle,"017a")
  s u69=##class(User.MARC).getTagX(.handle,"U69")
  s data("REASON")=##class(User.MARC).getSubTagStr(u69,"a")
  s:$$$GETLANGUAGE=3 data("REASON")=##class(User.MARC).getSubTagStr(u69,"b")
  s data("ERASEDATE")=##class(util.date).dtDisp(##class(User.MARC).getSubTagStr(u69,"d"))
} else {
  d ##class(i2.data.meta).all(.data,.handle)
}
